package com.wizzadrds.theworldremembers.dream; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*; public final class DreamManager extends SavedData {private final Map<UUID,Dream> dreams=new HashMap<>(); private static final Codec<Dream> D=RecordCodecBuilder.create(i->i.group(net.minecraft.core.UUIDUtil.CODEC.fieldOf("npc").forGetter(Dream::npcId),Codec.STRING.xmap(DreamType::valueOf,DreamType::name).fieldOf("type").forGetter(Dream::type),Codec.LONG.fieldOf("epoch").forGetter(Dream::sleepEpoch),Codec.STRING.fieldOf("text").forGetter(Dream::text),Codec.BOOL.fieldOf("factual").forGetter(Dream::factual)).apply(i,Dream::new)); private static final Codec<DreamManager>C=Codec.unboundedMap(net.minecraft.core.UUIDUtil.CODEC,D).xmap(m->{var x=new DreamManager();x.dreams.putAll(m);return x;},x->x.dreams); private static final SavedDataType<DreamManager>TYPE=new SavedDataType<>(net.minecraft.resources.Identifier.fromNamespaceAndPath("the_world_remembers","dreams"),DreamManager::new,C,null); public static DreamManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new DreamManager():l.getDataStorage().computeIfAbsent(TYPE);} public Dream get(UUID id){return dreams.get(id);} public Dream remember(Dream d){dreams.put(d.npcId(),d);setDirty();return d;}}
